#!/usr/bin/env python3
"""Rapport statique vérifiable de la paire LOT_034/035 ; aucune modification des leçons."""
from pathlib import Path
from datetime import datetime,timezone
from html import escape
import csv,io,json,hashlib
from lxml import html
B=Path(__file__).resolve().parents[1]
D=B/'bilan_034_035';D.mkdir(exist_ok=True)
rows=[]
for n in (34,35):
 lot=f'LOT_{n:03}';p=B/lot/'audits/validation_v8_finale.json';d=json.loads(p.read_text())
 assert d['statique_ok'] and len(d['fichiers'])==11
 for f in d['fichiers']:
  path=B/lot/f['fichier'];raw=path.read_bytes();assert hashlib.sha256(raw).hexdigest()==f['sha256'] and len(raw)==f['octets']
  tree=html.document_fromstring(raw);title=tree.xpath('//main/h2')[0].text_content();phase='Phase_A' in f['fichier'];limit=100000 if phase else 9000
  rows.append(dict(lot=lot,lecon='Phase A' if phase else f'DX.{f["fichier"].split("DX.")[1].split(".html")[0]}',titre=title,chemin=f'{lot}/{f["fichier"]}',x=f['texte_fiche_octets'],y=f['texte_fenetres_octets'],xy=f['texte_fiche_octets']+f['texte_fenetres_octets'],html=f['octets'],limite=limit,taille_v8=f['texte_fiche_octets']<=limit,ancien_80_150=80000<=f['octets']<=150000,v8=sum(c['ok']for c in f['controles']),citations=f['citations_aips'],sha256=f['sha256']))
now=datetime.now(timezone.utc).isoformat(timespec='seconds');summary={'date_utc':now,'lots':[34,35],'lecons':len(rows),'parties':14*len(rows),'questions':14*len(rows),'v8':sum(r['v8']for r in rows),'citations_aips':sum(r['citations']for r in rows),'sous_80_ko':sum(r['html']<80000 for r in rows),'plus_150_ko':sum(r['html']>150000 for r in rows),'audit_independant':False,'navigateur':False,'validation_clinique':False}
(D/'mesures.json').write_text(json.dumps({'bilan':summary,'lecons':rows},ensure_ascii=False,indent=2)+'\n')
s=io.StringIO();w=csv.DictWriter(s,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows);(D/'mesures.csv').write_text(s.getvalue())
def ko(n):return f'{n/1000:.3f}'.replace('.',',')
def cell(r):
 verdict='Dans la bande' if r['ancien_80_150'] else 'Sous 80 Ko' if r['html']<80000 else 'Dépasse 150 Ko'
 return f'''<tr><th scope="row"><a href="{r['chemin']}">{escape(('Phase A — ' if r['lecon']=='Phase A' else '')+r['titre'])}</a></th><td>{ko(r['x'])}</td><td>{ko(r['y'])}</td><td>{ko(r['xy'])}</td><td><strong>{ko(r['html'])}</strong></td><td class="ok">Oui<small>{r['x']/r['limite']*100:.1f} % du plafond de {r['limite']//1000} Ko</small></td><td class="{'ok' if r['ancien_80_150'] else 'warn'}">{verdict}</td><td>{r['v8']}/25</td><td>{r['citations']}</td></tr>'''
sections=[]
for n,label in [(34,'Ronflement'),(35,'Mal de gorge')]:
 lot=f'LOT_{n:03}';proof='audits/RELECTURE_FINALE.md' if n==34 else 'audits/RELECTURE_TRANSVERSALE.md';rs=[r for r in rows if r['lot']==lot]
 sections.append(f'''<section><h2>{lot} · {label}</h2><p>11 leçons, 154 questions, 275 contrôles statiques positifs. <a href="{lot}/{proof}">Relecture interne</a> · <a href="{lot}/HELP.md">Limites cliniques et documentaires</a> · <a href="{lot}/audits/validation_v8_finale.json">Preuves V8 et empreintes</a></p><div class="scroll"><table><caption>Tailles en Ko décimaux ; les colonnes de texte ne sont pas des poids de fichiers HTML.</caption><thead><tr><th scope="col">Leçon</th><th scope="col">Fiche x<br>sans fenêtres</th><th scope="col">Détails y</th><th scope="col">Texte x+y<br>avec fenêtres</th><th scope="col">Fichier HTML<br>complet</th><th scope="col">Taille V8</th><th scope="col">Ancienne bande<br>80–150 Ko</th><th scope="col">Contrôles V8</th><th scope="col">Citations AIPS</th></tr></thead><tbody>{''.join(cell(r) for r in rs)}</tbody></table></div></section>''')
out=f'''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Bilan des LOT_034 et LOT_035</title><style>
:root{{font-family:system-ui,sans-serif;color:#172d36;background:#f4f7f6;line-height:1.55}}body{{max-width:1500px;margin:auto;padding:32px}}h1{{font-size:clamp(1.8rem,4vw,3rem);line-height:1.15}}h2{{margin-top:0}}a{{color:#075d80}}section,.note{{background:white;border:1px solid #d4e1e2;border-radius:12px;padding:24px;margin:24px 0}}.cards{{display:flex;flex-wrap:wrap;gap:14px}}.cards p{{flex:1;min-width:150px;background:#123c49;color:white;padding:18px;border-radius:10px;margin:0}}.cards strong{{display:block;font-size:2rem}}table{{border-collapse:collapse;width:100%;font-size:.9rem}}th,td{{border-bottom:1px solid #d4e1e2;padding:13px 10px;text-align:right;vertical-align:top}}thead th{{background:#e6eef0}}th:first-child{{text-align:left;min-width:245px}}td{{font-variant-numeric:tabular-nums}}small{{display:block;white-space:normal;font-size:.75rem}}.scroll{{overflow:auto}}.ok{{color:#14613f}}.warn{{color:#855000}}caption{{text-align:left;padding-bottom:14px}}code{{word-break:break-all}}@media print{{body{{padding:0;background:white}}section{{break-inside:avoid;padding:12px}}.scroll{{overflow:visible}}table{{font-size:8pt}}}}</style></head><body><header><p>Chantier LOTS · relevé du {escape(now)}</p><h1>Deux lots produits en parallèle</h1><p>LOT_034 : ronflement. LOT_035 : mal de gorge. Ce bilan porte sur les 22 leçons de cette paire et conserve les limites réelles des contrôles.</p></header><div class="cards"><p><strong>22</strong>leçons HTML</p><p><strong>308</strong>questions</p><p><strong>{summary['v8']}/550</strong>contrôles statiques V8 positifs</p><p><strong>{summary['citations_aips']}</strong>citations AIPS retrouvées</p></div>
<section><h2>Ce qui est vérifié</h2><p><strong>Taille : oui selon V8.</strong> Le <a href="PROMPT_CODEX.md">prompt Codex, section 8</a> fixe 9 Ko de texte de fiche par monographie et 100 Ko pour la leçon principale, fenêtres et dépliants exclus. Les 22 fichiers respectent ces plafonds.</p><p><strong>Ancienne bande de 80–150 Ko :</strong> {22-summary['sous_80_ko']-summary['plus_150_ko']} fichiers dans la bande, {summary['sous_80_ko']} sous 80 Ko et {summary['plus_150_ko']} au-dessus de 150 Ko. Aucun remplissage n’a été ajouté pour augmenter artificiellement le poids.</p><p><strong>Langue et fond :</strong> relectures internes et corrections tracées. Les rapports historiques restent négatifs, notamment pour les titres d’abréviation, la forme des sources ou les anciennes attentes de balisage et de taille. Leur négativité n’a pas été effacée. Le comptage des citations AIPS vérifie leur présence dans les notices archivées ; il ne certifie pas toutes les indications ou omissions.</p><p><strong>Conformité intégrale du prompt : non démontrée.</strong> Aucun audit médical indépendant, aucune validation clinique ni aucun essai navigateur. Les limites de prescriptions hospitalières et les divergences entre recommandations et notices sont détaillées dans chaque HELP.</p></section>
<div class="note"><h2>Comment lire les tailles</h2><p>1 Ko = 1 000 octets. <strong>x</strong> mesure le texte de la fiche ; <strong>y</strong> celui des fenêtres et dépliants ; <strong>x+y</strong> leur somme. Le poids du <strong>fichier HTML complet</strong> inclut également le balisage, le style et les polices embarquées. Ouvrir une fenêtre ne change pas le poids du fichier : son contenu est déjà intégré.</p><p><a href="bilan_034_035/mesures.csv">Télécharger toutes les mesures en CSV</a> · <a href="bilan_034_035/mesures.json">Données et empreintes SHA-256</a> · <a href="ETAT_DES_LIEUX.html">Rapport précédent : instantané des 170 leçons</a>. Ce dernier conserve sa date et son périmètre ; il ne représente pas la production actuelle complète.</p></div>{''.join(sections)}<footer><p>Rapport généré à partir des fichiers réels et des contrôles finaux, sans modifier les leçons. Sources et manuscrits exacts conservés dans chaque dossier.</p></footer></body></html>'''
report=B/'BILAN_LOTS_034_035.html';report.write_text(out)
t=html.document_fromstring(report.read_bytes());trs=t.xpath('//tbody/tr');assert len(trs)==22
checks=0
for tr,r in zip(trs,rows):
 cells=tr.xpath('./td');v=[int(c.text_content().replace(',',''))for c in cells[:4]];assert v==[r['x'],r['y'],r['xy'],r['html']];checks+=1
for href in t.xpath('//a/@href'):assert (B/href).is_file(),href;checks+=1
assert not t.xpath('//script|//iframe|//*[@src]');checks+=1
assert sum(r['v8']for r in rows)==550 and all(r['taille_v8']for r in rows);checks+=1
(D/'verification.json').write_text(json.dumps({'date':now,'controles_reussis':checks,'rapport_sha256':hashlib.sha256(report.read_bytes()).hexdigest(),'mesures':True,'liens':True,'navigateur':False,'validation_clinique':False},indent=2)+'\n')
print(json.dumps(summary,ensure_ascii=False));print('Vérifications du rapport :',checks)
